# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""In-place ``aten::_foreach_erf_(Tensor(a!)[] self) -> ()``.

Iteration 2: the whole tensor list is packed into a single launch per dtype.

* Dense layouts (contiguous, transposed, permuted - anything whose memory span is
  exactly ``[data_ptr, data_ptr + numel)``) go into one 2-D launch
  ``(tensor_slot, block)`` with up to ``_MAXT`` tensors selected by a uniform
  branch on ``program_id(0)``.  Erf costs the same in every slot, so one launch
  serves the entire list where the previous version needed one launch per
  tensor (a launch costs ~55 us of wall time here, ATen amortises to ~4 us).
* Gappy views keep the inner-run strided kernel, one launch each.
* Erf is evaluated in float32 (ATen's opmath for 16-bit inputs) with
  ``tl.math.erf`` and rounded back to the tensor dtype.
"""

import torch
import triton
import triton.language as tl

_BLOCK = 16384
_BLOCK_STRIDED = 2048
_MAXT = 16
_MAXOUT = 4

_FAST_DTYPES = (torch.float16, torch.bfloat16, torch.float32)


@triton.jit
def _erf_flat_kernel(x_ptr, n, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < n
    x = tl.load(x_ptr + offs, mask=m, other=0.0)
    tl.store(
        x_ptr + offs,
        tl.math.erf(x.to(tl.float32)).to(x_ptr.dtype.element_ty),
        mask=m,
    )


@triton.jit
def _erf_pack_kernel(
    x_base,
    o0: tl.int64,
    o1: tl.int64,
    o2: tl.int64,
    o3: tl.int64,
    o4: tl.int64,
    o5: tl.int64,
    o6: tl.int64,
    o7: tl.int64,
    o8: tl.int64,
    o9: tl.int64,
    o10: tl.int64,
    o11: tl.int64,
    o12: tl.int64,
    o13: tl.int64,
    o14: tl.int64,
    o15: tl.int64,
    n0,
    n1,
    n2,
    n3,
    n4,
    n5,
    n6,
    n7,
    n8,
    n9,
    n10,
    n11,
    n12,
    n13,
    n14,
    n15,
    BLOCK: tl.constexpr,
):
    """``_MAXT`` dense tensors in one launch.

    Axis 0 selects the tensor, axis 1 the block inside it.  The selection is a
    chain of scalar ``tl.where`` on integer element offsets relative to
    ``x_base`` rather than a pointer-valued control-flow merge: this backend's
    ``TritonToUnstructureIncubated`` pass rejects an ``scf.if`` that yields
    ``!tt.ptr``, while integer selects lower cleanly.
    """
    t = tl.program_id(0)
    off = tl.where(t == 0, o0, o1)
    off = tl.where(t == 2, o2, off)
    off = tl.where(t == 3, o3, off)
    off = tl.where(t == 4, o4, off)
    off = tl.where(t == 5, o5, off)
    off = tl.where(t == 6, o6, off)
    off = tl.where(t == 7, o7, off)
    off = tl.where(t == 8, o8, off)
    off = tl.where(t == 9, o9, off)
    off = tl.where(t == 10, o10, off)
    off = tl.where(t == 11, o11, off)
    off = tl.where(t == 12, o12, off)
    off = tl.where(t == 13, o13, off)
    off = tl.where(t == 14, o14, off)
    off = tl.where(t == 15, o15, off)
    n = tl.where(t == 0, n0, n1)
    n = tl.where(t == 2, n2, n)
    n = tl.where(t == 3, n3, n)
    n = tl.where(t == 4, n4, n)
    n = tl.where(t == 5, n5, n)
    n = tl.where(t == 6, n6, n)
    n = tl.where(t == 7, n7, n)
    n = tl.where(t == 8, n8, n)
    n = tl.where(t == 9, n9, n)
    n = tl.where(t == 10, n10, n)
    n = tl.where(t == 11, n11, n)
    n = tl.where(t == 12, n12, n)
    n = tl.where(t == 13, n13, n)
    n = tl.where(t == 14, n14, n)
    n = tl.where(t == 15, n15, n)
    offs = tl.program_id(1) * BLOCK + tl.arange(0, BLOCK)
    p = (x_base + off) + offs
    m = offs < n
    x = tl.load(p, mask=m, other=0.0)
    tl.store(
        p,
        tl.math.erf(x.to(tl.float32)).to(x_base.dtype.element_ty),
        mask=m,
    )


@triton.jit
def _erf_strided_kernel(
    x_ptr,
    base,
    I,
    istride,
    nbi,
    o0,
    q0,
    o1,
    q1,
    o2,
    q2,
    o3,
    q3,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    outer = pid // nbi
    bi = pid - outer * nbi
    off = (outer % o0) * q0
    outer = outer // o0
    off += (outer % o1) * q1
    outer = outer // o1
    off += (outer % o2) * q2
    outer = outer // o2
    off += (outer % o3) * q3
    idx = bi * BLOCK + tl.arange(0, BLOCK)
    m = idx < I
    p = x_ptr + (base + off) + idx * istride
    x = tl.load(p, mask=m, other=0.0)
    tl.store(
        p,
        tl.math.erf(x.to(tl.float32)).to(x_ptr.dtype.element_ty),
        mask=m,
    )


def _is_dense_span(t):
    """True when ``[data_ptr, data_ptr + numel)`` covers exactly the tensor."""
    if t.is_contiguous():
        return True
    if t.numel() <= 1:
        return True
    expected = 1
    for s, sz in sorted((s, sz) for s, sz in zip(t.stride(), t.shape) if sz != 1):
        if s != expected:
            return False
        expected *= sz
    return True


def _launch_pack(pack, numels):
    nb = 0
    for n in numels:
        nb = max(nb, (n + _BLOCK - 1) // _BLOCK)
    base = pack[0]
    p0 = base.data_ptr()
    isz = base.element_size()
    offs = [(t.data_ptr() - p0) // isz for t in pack]
    offs += [0] * (_MAXT - len(offs))
    ns = list(numels) + [0] * (_MAXT - len(numels))
    _erf_pack_kernel[(len(pack), nb)](base, *offs, *ns, _BLOCK, num_stages=1)


def _launch_strided(t, base, dims):
    if len(dims) > _MAXOUT + 1:
        sz, s = dims[0]
        for i in range(sz):
            _launch_strided(t, base + i * s, dims[1:])
        return
    # dims[i] = (size, stride); the smallest stride is the innermost run.
    inner = 0
    for i in range(1, len(dims)):
        if dims[i][1] < dims[inner][1]:
            inner = i
    I, istride = dims[inner]
    outer = dims[:inner] + dims[inner + 1 :]
    nbi = (I + _BLOCK_STRIDED - 1) // _BLOCK_STRIDED
    o = [(1, 0)] * _MAXOUT
    for i, (sz, s) in enumerate(outer):
        o[i] = (sz, s)
    n_outer = 1
    for sz, _s in outer:
        n_outer *= sz
    grid = (n_outer * nbi,)
    _erf_strided_kernel[grid](
        t,
        base,
        I,
        istride,
        nbi,
        o[0][0],
        o[0][1],
        o[1][0],
        o[1][1],
        o[2][0],
        o[2][1],
        o[3][0],
        o[3][1],
        _BLOCK_STRIDED,
    )


def _launch_gappy(t):
    dims = [(sz, s) for sz, s in zip(t.shape, t.stride()) if sz > 1]
    if not dims:
        _erf_flat_kernel[(1,)](t, 1, _BLOCK)
        return
    # Merge adjacent dims that are already memory-contiguous.
    merged = [dims[0]]
    for sz, s in dims[1:]:
        psz, ps = merged[-1]
        if ps == s * sz:
            merged[-1] = (psz * sz, s)
        else:
            merged.append((sz, s))
    _launch_strided(t, 0, merged)


def foreach_erf_(self):
    if not isinstance(self, (list, tuple)):
        raise TypeError(
            "argument 'self' (position 1) must be tuple of Tensors, not "
            + type(self).__name__
        )
    if len(self) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")
    for t in self:
        if not isinstance(t, torch.Tensor):
            raise TypeError(
                "argument 'self' (position 1) must be tuple of Tensors, not "
                + type(t).__name__
            )
        dt = t.dtype
        if dt not in _FAST_DTYPES:
            raise RuntimeError(
                "result type Float can't be cast to the desired output type "
                + str(dt).replace("torch.", "").capitalize()
            )

    packs = {}
    for t in self:
        n = t.numel()
        if n == 0:
            continue
        if _is_dense_span(t):
            lst = packs.get(t.dtype)
            if lst is None:
                packs[t.dtype] = [t]
            else:
                lst.append(t)
        else:
            _launch_gappy(t)

    for pack in packs.values():
        nt = len(pack)
        if nt == 1:
            t = pack[0]
            n = t.numel()
            _erf_flat_kernel[((n + _BLOCK - 1) // _BLOCK,)](t, n, _BLOCK, num_stages=1)
            continue
        # Identical tensors listed twice are written once: the reference foreach
        # batches them into one apply, so it produces erf(x) rather than
        # erf(erf(x)), and de-duplicating also removes the write race.
        seen = set()
        uniq = []
        for t in pack:
            key = t.data_ptr()
            if key in seen:
                continue
            seen.add(key)
            uniq.append(t)
        if len(uniq) == 1:
            t = uniq[0]
            n = t.numel()
            _erf_flat_kernel[((n + _BLOCK - 1) // _BLOCK,)](t, n, _BLOCK, num_stages=1)
            continue
        numels = [t.numel() for t in uniq]
        for i in range(0, len(uniq), _MAXT):
            _launch_pack(uniq[i : i + _MAXT], numels[i : i + _MAXT])
    return None
